{"cmd":"python3 - <<'PY'
from pathlib import Path
import re, subprocess
patches={p.stem for p in Path('/workspace/requirement_patches').glob('*.diff')}
for path in sorted(Path('/workspace/requirements').glob('*.yaml')):
    slug=path.stem
    if slug in patches:
        continue
    txt=path.read_text()
    ids=sorted(set(re.findall(r'JENKINS-\d+', txt)))
    patterns=ids or [slug.replace('-', ' ')]
    matches=[]
    for pat in patterns:
        out=subprocess.run(['git','-C','/workspace','log','--all','--oneline',f'--grep={pat}'],capture_output=True,text=True).stdout.strip().splitlines()
        if out:
            matches.extend(out[:5])
    # dedupe keep order
    seen=[]
    for m in matches:
        if m not in seen:
            seen.append(m)
    print(slug)
    print('IDS:', ', '.join(ids) if ids else '-')
    for m in seen[:5]:
        print('  ',m)
    print()
PY","workdir":"/workspace","yield_time_ms":1000,"max_output_tokens":20000}

