        if (ResourceDomainConfiguration.isResourceRequest(req)) {
            rsp.forward(this, "_404_simple", req);
        } else {
            final Object attribute = req.getAttribute(ErrorAttributeFilter.USER_ATTRIBUTE);
            if (attribute instanceof Authentication) {
